B64
tar xzf p.tgz
echo ">> adun codul Oberon de pe telefon"
find ~ -maxdepth 9 -type f \( -name '*.Mod' -o -name '*.obn' -o -name '*.ob07' -o -name '*.ob2' \) -size -400k \
  -not -path "$W/*" -not -path '*/.cache/*' -print0 2>/dev/null | xargs -0 -r md5sum | sort -s -k1,1 -u | cut -c35- | sort > lista.txt || true
: > assets/hrana-telefon.txt
n=0; tot=0; T='~'
while IFS= read -r f; do
  [ -f "$f" ] || continue
  s=$(wc -c < "$f"); tot=$((tot+s))
  if [ $tot -gt 30000000 ]; then echo "   (m-am oprit la 30 MB)"; break; fi
  printf '\n\036%s\n' "${f/#$HOME/$T}" >> assets/hrana-telefon.txt
  cat "$f" >> assets/hrana-telefon.txt
  n=$((n+1))
done < lista.txt
echo "   $n fisiere Oberon de pe telefon ($((tot/1024)) KB)"
[ -s assets/hrana-telefon.txt ] || rm -f assets/hrana-telefon.txt
mkdir -p assets/eula && cp oberon/*.Mod assets/eula/
echo ">> atelierul de rulat: oberonc + dx in aplicatie"
mkdir -p assets/rulare/bin comp rt
cp oberonc/*.class comp/
for c in OberonRuntime Out In Files Files_FileDesc Math Strings Os; do cp oberonc/$c.class rt/; done
for m in Out In Files Math Strings Os; do cp oberonc/$m.smb assets/rulare/bin/; done
dx --dex --output=assets/rulare/compilator.jar comp
dx --dex --output=assets/rulare/rt.jar rt
P=${PREFIX:-/data/data/com.termux/files/usr}
DXJ="$P/share/dex/dx.jar"
[ -s "$DXJ" ] || DXJ=$(sed -n 's/.*-cp \([^ ]*dx\.jar\).*/\1/p' "$(command -v dx)" 2>/dev/null | head -1)
if [ -s "$DXJ" ]; then cp "$DXJ" assets/rulare/dx.jar
else curl -L -o assets/rulare/dx.jar https://github.com/termux/distfiles/releases/download/2021.01.04/dx-android-1.16.jar; fi
[ -s assets/rulare/compilator.jar ] && [ -s assets/rulare/rt.jar ] && [ -s assets/rulare/dx.jar ] || { echo "EROARE: atelierul de rulat nu e complet"; exit 1; }
echo "   compilator $(( $(wc -c < assets/rulare/compilator.jar) / 1024 )) KB, dx $(( $(wc -c < assets/rulare/dx.jar) / 1024 )) KB"
echo ">> sistemul Oberon al terminalului (Shell, Fisiere, Net, Module + nucleul)"
mkdir -p sis/ob sis/cls assets/sistem
OBERON_BIN="$W/oberonc" java -cp oberonc oberonc sis/ob sistem/def/Param.Mod sistem/def/Dosar.Mod sistem/def/Retea.Mod sistem/def/Nucleu.Mod sistem/def/Senzor.Mod sistem/def/Ecran.Mod sistem/def/Sunet.Mod sistem/def/Conversatie.Mod sistem/def/Pachet.Mod \
  sistem/Fisiere.Mod sistem/Net.Mod sistem/Module.Mod sistem/Aplicatie.Mod sistem/Shell.Mod
for m in Fisiere Net Module Aplicatie Shell; do [ -f sis/ob/$m.class ] || { echo "EROARE: modulul $m nu s-a compilat"; exit 1; }; done
javac --release 8 -nowarn -encoding UTF-8 -d sis/cls sistem/java/*.java src/ro/jahbalon/eulaoberon/Rulator.java src/ro/jahbalon/eulaoberon/Dx.java
cp sis/ob/*.class sis/cls/
for c in OberonRuntime Out In Files Files_FileDesc Math Strings Os; do cp oberonc/$c.class sis/cls/; done
dx --dex --output=assets/rulare/sistem.jar sis/cls
[ -s assets/rulare/sistem.jar ] || { echo "EROARE: sistem.jar lipseste"; exit 1; }
for m in Param Dosar Retea Nucleu Senzor Ecran Sunet Conversatie Pachet Fisiere Net Module Aplicatie; do cp sis/ob/$m.smb assets/rulare/bin/; done
echo ">> lansatorul aplicatiilor Oberon (pentru apk X.Mod)"
J=~/android.jar
[ -s "$J" ] || curl -L -o "$J" https://raw.githubusercontent.com/Sable/android-platforms/master/android-34/android.jar
mkdir -p apcls
javac --release 8 -nowarn -encoding UTF-8 -cp "$J" -d apcls $(find aplicatie/java -name '*.java')
for c in OberonRuntime Out In Files Files_FileDesc Math Strings Os; do cp oberonc/$c.class apcls/; done
(cd apcls && zip -q -r ../assets/rulare/aplicatie.jar .)
[ -s assets/rulare/aplicatie.jar ] || { echo "EROARE: aplicatie.jar lipseste"; exit 1; }
echo ">> pielea paginilor HTML (pentru html X.html)"
mkdir -p pgcls
javac --release 8 -nowarn -encoding UTF-8 -cp "$J" -d pgcls pagina/ro/jahbalon/webapp/Pagina.java
dx --dex --output=assets/rulare/pagina.dex pgcls
[ -s assets/rulare/pagina.dex ] || { echo "EROARE: pagina.dex lipseste"; exit 1; }
cp sistem/*.Mod sistem/def/*.Mod assets/sistem/
mkdir -p assets/exemple assets/exemple-vechi && cp -r sistem/exemple/* assets/exemple/ && cp sistem/exemple-vechi/* assets/exemple-vechi/
echo "   sistem.jar $(( $(wc -c < assets/rulare/sistem.jar) / 1024 )) KB"
J=~/android.jar
[ -s "$J" ] || curl -L -o "$J" https://raw.githubusercontent.com/Sable/android-platforms/master/android-34/android.jar
echo ">> aapt2"
RES=""
if [ -d res ] && aapt2 compile --dir res -o res.zip; then RES=res.zip; fi
if ! aapt2 link -o base.apk -I "$J" --manifest AndroidManifest.xml -A assets $RES --min-sdk-version 21 --target-sdk-version 28; then
  echo "(iconul nu a mers cu aapt2-ul tau; construiesc fara el)"
  sed -i 's# android:icon="@mipmap/ic_launcher" android:roundIcon="@mipmap/ic_launcher"##' AndroidManifest.xml
  aapt2 link -o base.apk -I "$J" --manifest AndroidManifest.xml -A assets --min-sdk-version 21 --target-sdk-version 28
fi
echo ">> oberonc (modulele Oberon ale Eulei)"
mkdir -p ob
M="Litere Disc Iesire Gramatica Memorie Soroban7 Raport Roler Motor Lectii Fire Eula"
OBERON_BIN="$W/oberonc" java -cp oberonc oberonc ob $(for m in $M; do echo oberon/$m.Mod; done)
for m in $M; do [ -f ob/$m.class ] || { echo "EROARE: modulul $m nu s-a compilat"; exit 1; }; done
echo "   12 module Oberon compilate"
echo ">> javac (pielea)"
mkdir -p cls
javac --release 8 -nowarn -encoding UTF-8 -cp "$J" -d cls $(find src -name '*.java')
cp ob/*.class cls/
cp oberonc/OberonRuntime.class oberonc/Files.class oberonc/Files_FileDesc.class oberonc/Math.class cls/
echo ">> dx"
dx --dex --output=classes.dex cls
[ -s classes.dex ] || { echo "EROARE: classes.dex lipseste"; exit 1; }
zip -j -q base.apk classes.dex
mkdir -p lib/arm64-v8a lib/armeabi-v7a
cp native/eulapty-aarch64-linux-musl lib/arm64-v8a/libeulapty.so
cp native/eulapty-arm-linux-musleabihf lib/armeabi-v7a/libeulapty.so
cp native/infernoemu-aarch64 lib/arm64-v8a/libinfernoemu.so
zip -r -q -D base.apk lib
echo ">> semnez"
[ -f ~/eula.keystore ] || keytool -genkeypair -keystore ~/eula.keystore -storepass jahbalon -keypass jahbalon -alias eula -keyalg RSA -keysize 2048 -validity 10000 -dname "CN=Pion, O=Jahbalon Research"
apksigner sign --ks ~/eula.keystore --ks-pass pass:jahbalon --key-pass pass:jahbalon --out EulaOberon.apk base.apk
cp EulaOberon.apk ~/storage/downloads/EulaOberon.apk
echo ">> GATA: ~/storage/downloads/EulaOberon.apk"
termux-open EulaOberon.apk




